// Pick one customer by offset (passed via ?offset=N query param)
const trigger = $('Webhook Trigger').first().json;
const offset = parseInt(trigger.query?.offset || '0');
const customers = $('Fetch Customers').first().json.data || [];
const withEmail = customers.filter(c => c.email && c.email.trim());
const c = withEmail[offset];
if (!c) throw new Error('No customer at offset ' + offset + ' (total with email: ' + withEmail.length + ')');
return [{ json: {
  customer_id: c.id,
  customerEmail: c.email.trim().toLowerCase(),
  customerFirstName: c.first_name || c.contact_first_name || '',
  customerLastName: c.last_name || c.contact_last_name || '',
  customerPhone: c.phone || c.mobile || ''
} }];

// Get lifetime value from all sales, output sale IDs for individual fetch (limit 20)
const salesResp = $json;
const sales = salesResp.data || [];
const customer = $('Pick Customer').first().json;

let lifetimeValue = 0;
const saleIds = [];
for (const sale of sales) {
  const totals = sale.totals || {};
  lifetimeValue += parseFloat(totals.total_price || sale.total_price || 0);
  saleIds.push({
    id: sale.id,
    invoiceNumber: sale.invoice_number,
    saleDate: sale.sale_date,
    saleNote: sale.note || '',
    cashier: (sale.user && sale.user.name) || '',
    totals
  });
}

// Limit to 20 most recent for product lookups
const toFetch = saleIds.slice(-20);
return toFetch.map(s => ({ json: {
  ...s,
  customer_id: customer.customer_id,
  customerEmail: customer.customerEmail,
  customerFirstName: customer.customerFirstName,
  customerLastName: customer.customerLastName,
  customerPhone: customer.customerPhone,
  totalSalesCount: sales.length,
  lifetimeValue
} }));

// Collect unique product_ids from all fetched sale details
const saleDetails = $('Fetch Sale Detail').all();
const saleMetadata = $('Split Sale IDs').all();
const productIdsNeeded = new Set();
const salesWithProducts = [];

for (let i = 0; i < saleDetails.length; i++) {
  const saleResp = saleDetails[i].json;
  const sale = saleResp.data || saleResp;
  const meta = saleMetadata[i] ? saleMetadata[i].json : {};
  const prods = sale.line_items || sale.register_sale_products || [];

  const saleProds = [];
  for (const p of prods) {
    productIdsNeeded.add(p.product_id);
    saleProds.push({
      product_id: p.product_id,
      price: p.price,
      quantity: p.quantity,
      note: p.note || ''
    });
  }
  salesWithProducts.push({
    invoiceNumber: meta.invoiceNumber || sale.invoice_number,
    saleDate: meta.saleDate || sale.sale_date,
    saleTotal: parseFloat((sale.totals || {}).total_price || (meta.totals || {}).total_price || 0),
    saleNote: meta.saleNote || sale.note || '',
    cashier: meta.cashier || (sale.user && sale.user.name) || '',
    products: saleProds
  });
}

const firstMeta = saleMetadata[0] ? saleMetadata[0].json : {};

return Array.from(productIdsNeeded).map(pid => ({ json: {
  product_id: pid,
  _customerEmail: firstMeta.customerEmail,
  _customerFirstName: firstMeta.customerFirstName,
  _customerLastName: firstMeta.customerLastName,
  _customerPhone: firstMeta.customerPhone,
  _totalSalesCount: firstMeta.totalSalesCount,
  _lifetimeValue: firstMeta.lifetimeValue,
  _salesWithProducts: salesWithProducts
} }));

// Build product cache, then generate tags and notes
const typesResp = $('Fetch Product Types').first().json;
const typeMap = {};
for (const pt of (typesResp.data || [])) {
  typeMap[pt.id] = (pt.name || '').toLowerCase().trim();
}

const fetchedProducts = $('Fetch Product').all();
const productCache = {};
for (const fp of fetchedProducts) {
  const p = fp.json.data || fp.json;
  if (p && p.id) {
    productCache[p.id] = {
      name: p.name || p.variant_name || 'Unknown',
      typeName: typeMap[p.product_type_id] || ''
    };
  }
}

// Get metadata from first Collect Product IDs item
const meta = $('Collect Product IDs').first().json;
const salesWithProducts = meta._salesWithProducts;

const categoryTagMap = {
  'tattoo artist': '[client] tattoo',
  'microblader': '[client] tattoo',
  'piercing': '[client] piercing',
  'piercer': '[client] piercing',
  'tooth gem': '[client] piercing'
};

const jewelryTypes = new Set(['ring', 'charm', 'plug', 'barbell', 'surface', 'threaded ends',
  'retainer', 'threadless post', 'earrings', 'threaded post', 'chain', 'titanium', 'gold',
  'threadless top', 'navel curve', 'hanger', 'glass', 'organics (bone/wood/etc)',
  'metal (gold/titanium/stainless steel/etc)', 'ear cuff', 'threader']);

const tags = new Set(['[system] lightspeed-customer']);
if (meta._lifetimeValue >= 500) tags.add('[system] vip');

const allNotes = [];

for (const sale of salesWithProducts) {
  const datePart = sale.saleDate ? sale.saleDate.split('T')[0] : '?';
  const noteLines = [];
  noteLines.push('Sale ' + sale.invoiceNumber + ' — ' + datePart + ' — $' + sale.saleTotal.toFixed(2));
  if (sale.cashier) noteLines.push('Cashier: ' + sale.cashier);
  noteLines.push('');

  for (const sp of sale.products) {
    const cached = productCache[sp.product_id] || { name: 'Unknown', typeName: '' };
    const typeName = cached.typeName;
    const productName = cached.name;

    for (const [key, tag] of Object.entries(categoryTagMap)) {
      if (typeName.includes(key)) tags.add(tag);
    }
    if (['tattoo artist', 'microblader'].some(t => typeName.includes(t))) {
      tags.add('[client] tattoo: ' + productName.toLowerCase().trim());
    }
    if (typeName === 'piercer') {
      tags.add('[client] piercing: ' + productName.toLowerCase().trim());
    }
    if (typeName === 'piercing' && productName.toLowerCase().startsWith('piercing')) {
      const location = productName.replace(/^piercing\s*-\s*/i, '').toLowerCase().trim();
      if (location) tags.add('[client] piercing: ' + location);
    }
    if (typeName === 'tooth gem') tags.add('[client] piercing: tooth gem');
    if (jewelryTypes.has(typeName)) tags.add('[client] jewelry: ' + productName.toLowerCase().trim());

    const price = parseFloat(sp.price || 0).toFixed(2);
    let line = '• ' + productName + ' ($' + price + ')';
    if (sp.note) line += '\n  → ' + sp.note;
    noteLines.push(line);
  }
  if (sale.saleNote) {
    noteLines.push('');
    noteLines.push('Sale note: ' + sale.saleNote);
  }
  allNotes.push(noteLines.join('\n'));
}

return [{ json: {
  customerEmail: meta._customerEmail,
  customerFirstName: meta._customerFirstName,
  customerLastName: meta._customerLastName,
  customerPhone: meta._customerPhone,
  totalSalesCount: meta._totalSalesCount,
  lifetimeValue: meta._lifetimeValue,
  tags: Array.from(tags),
  notes: allNotes,
  uniqueProducts: Object.keys(productCache).length,
  salesDetailFetched: salesWithProducts.length
} }];

const matcherData = $json;
const buildData = $('Build Tags + Notes').first().json;
return [{ json: { ...buildData, ghl_contact_id: matcherData.ghl_contact_id } }];

// Create one GHL note per sale (batch them into groups to avoid rate limits)
const data = $('Merge').first().json;
return data.notes.map(noteBody => ({ json: { ghl_contact_id: data.ghl_contact_id, noteBody } }));

const data = $('Merge').first().json;
const tagResult = $('Apply Tags').first().json;
const noteCount = $('Create GHL Note').all().length;
return [{ json: {
  customer: data.customerEmail,
  ghl_contact_id: data.ghl_contact_id,
  totalSales: data.totalSalesCount,
  salesDetailFetched: data.salesDetailFetched,
  lifetimeValue: '$' + data.lifetimeValue.toFixed(2),
  tagsApplied: data.tags,
  notesCreated: noteCount
} }];
